// Validates the request from BTC Scheduler. The webhook's Header Auth credential
// ("BTC Scheduler lookup token") has already checked the bearer token.
// Anything that is not a plausible email gets a 400 JSON response and no Salesforce call.
const body = $input.first().json.body || {};
const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const CONTROL = /[\u0000-\u001f\u007f]/;
if (!email || email.length > 254 || CONTROL.test(email) || !EMAIL.test(email)) {
  return [{ json: { ok: false, httpCode: 400, response: { error: 'invalid_email' } } }];
}

// SOQL string escaping, the same as the lead workflow: backslash first, then quote.
const esc = s => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
return [{ json: {
  ok: true,
  emailEsc: esc(email),
  sf_base: 'https://bigthink.my.salesforce.com/services/data/v60.0'
} }];

// Maps the two Salesforce query results to the BTC Scheduler lookup contract
// (docs/home-page.md). Only what the routing rules need leaves this workflow: no Salesforce
// Ids, names, stages or merchant fields. Any failed query answers 502 lookup_failed.
const failed = [{ json: { httpCode: 502, response: { error: 'lookup_failed' } } }];
const records = (name) => {
  let res;
  try { res = $(name).first().json; } catch (e) { return null; }
  if (!res || res.statusCode !== 200 || !res.body || !Array.isArray(res.body.records)) return null;
  return res.body.records;
};
const opps = records('Query Opportunities');
const leads = records('Query Leads');
if (!opps || !leads) return failed;

const email = v => (typeof v === 'string' && v.trim() ? v.trim().toLowerCase().slice(0, 254) : null);
const iso = v => {
  const t = Date.parse(v);
  return Number.isNaN(t) ? '' : new Date(t).toISOString();
};
const FUNDED = ['Funded', 'Renewal Prospecting'];

const opportunities = opps.slice(0, 50).map(o => {
  const owner = o.Owner && email(o.Owner.Email)
    ? { email: email(o.Owner.Email), active: o.Owner.IsActive === true, standard: o.Owner.UserType === 'Standard' }
    : null;
  const rc = o.Renewal_Closer__r;
  const renewalCloser = rc && email(rc.Email) ? { email: email(rc.Email), active: rc.IsActive === true } : null;
  const rawBook = o.Account ? o.Account.Renewal_Book__c : null;
  const book = typeof rawBook === 'string' && rawBook.trim() ? rawBook.trim().slice(0, 100) : null;
  return {
    open: !o.IsClosed,
    renewal: o.Is_Renewal_Type__c === true || o.StageName === 'Renewal',
    funded: FUNDED.includes(o.StageName),
    lastModified: iso(o.LastModifiedDate),
    owner,
    renewalCloser,
    book
  };
});

const leadList = leads.slice(0, 10).map(l => ({
  createdAt: iso(l.CreatedDate),
  owner: l.Owner && email(l.Owner.Email)
    ? { email: email(l.Owner.Email), active: l.Owner.IsActive === true, isUser: l.Owner.Type === 'User' }
    : null
}));

return [{ json: { httpCode: 200, response: { opportunities, leads: leadList } } }];
